if (!Object.keys(_st).length) { node.warn('startup check: HA states not loaded yet, skipping'); return [null, null]; }

const status = st('sensor.mr_slave_status_2');
const cleaning = st('binary_sensor.mr_slave_cleaning_2') === 'on'
    || st('vacuum.mr_slave_2') === 'cleaning'
    || ['segment_cleaning','zoned_cleaning','spot_cleaning','room_cleaning','cleaning'].includes(status);

if (cleaning) {
    node.status({fill:'yellow', text:'restart: robot still cleaning'});
    return [null, {notify: {title: 'Vacuum: automation restarted mid-run',
        message: 'Node-RED restarted while a clean was running. The robot is still going, but the automation lost track of this run and will not advance it or mark rooms. Tap Daily clean after it docks if anything was missed.',
        tag: 'rr_restart', urgent: false}}];
}

node.status({fill:'red', text:'restart: run interrupted'});
const evt = {rr_evt: 'failed', rr_phase: 'Interrupted by a restart'};
const notify = {notify: {title: 'Vacuum: run interrupted by a restart',
    message: 'Node-RED restarted during a clean and the robot is no longer cleaning. The run was stopped and no rooms were marked. Tap Daily clean to resume.',
    tag: 'rr_restart', urgent: false}};
return [evt, notify];

// Recharge watcher (replaces the single 'wait resume' wait, which hung for its
// whole timeout and then wrongly stamped every room). Polled every 2 min while
// the robot recharges mid-sweep.
//   resumed  -> status segment_cleaning: hand back to wait dock (rest) (out0)
//   dropped  -> progress reset to 0, or charged & battery >= 95 for ~10 min, or
//               150-min cap: robot will NOT resume. Go to the mop gate via d_55
//               WITHOUT f_ev_restdone (unfinished rooms stay unmarked) + notify.
//   waiting  -> loop back to d_rcpoll (out3)
// out0 -> [w_54, f_ev_rest], out1 -> d_55, out2 -> notify, out3 -> d_rcpoll
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return [null,null,null,null]; }
const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);
const status = st('sensor.mr_slave_status_2');
const batt = Number(st('sensor.mr_slave_battery_2'));
const prog = Number(st('sensor.mr_slave_cleaning_progress_2'));

// Resumed on its own (Roborock recharge & resume): the dock wait takes over again.
if (status === 'segment_cleaning') {
    node.status({fill:'green', text:'resumed'});
    return [msg, null, null, null];
}

const n = (msg.rr_rc_polls || 0) + 1;
msg.rr_rc_polls = n;
const chargedFull = !isNaN(batt) && batt >= 95 && ['charging','charged','docked'].includes(status);
msg.rr_rc_full = (msg.rr_rc_full || 0) + (chargedFull ? 1 : 0);

const dropped = (!isNaN(prog) && prog === 0) || msg.rr_rc_full >= 5 || n >= 75;
if (dropped) {
    const why = n >= 75 ? 'did not resume within 150 min'
        : (prog === 0 ? 'cleared its resume flag (progress reset to 0) after recharging'
        : 'finished charging but did not resume');
    node.status({fill:'yellow', text:'no resume: ' + why});
    const notify = {notify: {title: 'Vacuum: did not resume after recharge',
        message: 'The robot recharged mid-sweep but ' + why + '. Skipping the rest of the sweep and moving on; the unfinished rooms are left unmarked.',
        tag: 'rr_no_resume', urgent: true}};
    return [null, msg, notify, null];
}
node.status({fill:'blue', text:`waiting resume: ${batt}% batt, ${prog}% done (poll ${n})`});
return [null, null, null, msg];

// Central mop-failure notice: one alert (tag rr_mop_failed, urgent) whenever a
// mop pass does not complete. Deliberately does NOT stamp
// input_datetime.rr_last_mop_run. No catch-up since 2026-11-18 (rrMopDue is
// Wednesday only): a failed Wednesday mop waits for next Wednesday, or the
// owner taps "Mop all floors". Clears rr_mop_pending so the stall/stop alerts
// don't also mention the mop, and bumps rr_mopgen so no step poll of this pass
// carries on. out0 -> notify, out1 -> restore vacuum + done.
// Once the water watch has failed this pass, later failures of the same pass are dropped.
if (flow.get('rr_mop_water') && !msg.rr_mop_water) { node.status({fill:'grey',shape:'ring',text:'duplicate mop failure dropped'}); return [null, null]; }
flow.set('rr_mop_pending', false);
flow.set('rr_mop_inpass', 0);
flow.set('rr_mopgen', (flow.get('rr_mopgen') || 0) + 1);
const reason = msg.rr_mop_reason || 'it did not finish';
const manual = !!flow.get('rr_mop_manual');
const notify = manual
    ? {notify: {title: 'Vacuum: Mop all floors did not finish',
        message: 'The mop pass did not complete: ' + reason + '. Tap Mop all floors to try again.',
        tag: 'rr_mop_failed', urgent: true}}
    : {notify: {title: 'Vacuum: weekly mop did not finish',
        message: 'The weekly mop pass did not complete: ' + reason + '. There is no catch-up: the next mop is next Wednesday (or tap Mop all floors).',
        tag: 'rr_mop_failed', urgent: true}};
node.status({fill:'red', text:'mop failed'});
return [notify, msg];

// binary_sensor.mr_slave_water_shortage_2 turned on. Only matters while a mop
// pass is in progress (rr_mop_inpass = pass start ms, set by f_59). Sends
// the one urgent rr_mop_failed via f_mopfail and marks the pass incomplete
// (rr_last_mop_run is not stamped), so the next eligible day re-runs it.
// rr_mop_water makes f_mstep / f_mstepchk / f_mretry / f_mopfail drop the rest of this pass's loop.
const t0 = flow.get('rr_mop_inpass') || 0;
const run = flow.get('rr_run', 'file') || {};
if (!t0 || !run.active || flow.get('rr_cancel') || flow.get('rr_mop_water')) {
    node.status({fill:'grey', shape:'ring', text:'water shortage outside a mop pass'});
    return null;
}
flow.set('rr_mop_water', true);
flow.set('rr_mop_inpass', 0);
const mins = Math.max(0, Math.round((Date.now() - t0) / 60000));
msg.rr_mop_water = true;
msg.rr_mop_reason = 'the clean-water tank ran out ' + mins + ' min into the mop pass, so it is marked incomplete. Refill the tank';
node.status({fill:'red', text:'water ran out ' + mins + ' min into the mop'});
return msg;

// Arm 'w_42': bump the wait generation + mark it pending, and stamp the
// msg so this wait's own success/timeout can be told apart from a stale firing
// left armed after an HA-reconnect recovery (f_hareconn).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', 'w_42');
msg.rr_wgen = g;
return msg;

// Arm 'w_48': bump the wait generation + mark it pending, and stamp the
// msg so this wait's own success/timeout can be told apart from a stale firing
// left armed after an HA-reconnect recovery (f_hareconn).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', 'w_48');
msg.rr_wgen = g;
return msg;

// Arm 'w_54': bump the wait generation + mark it pending, and stamp the
// msg so this wait's own success/timeout can be told apart from a stale firing
// left armed after an HA-reconnect recovery (f_hareconn).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', 'w_54');
msg.rr_wgen = g;
if (!msg.rr_sweep_t0) msg.rr_sweep_t0 = Date.now();   // f_rc minimum-sweep check
return msg;

// Arm 'wait dock (office)': bump the wait generation + mark it pending, and
// stamp the msg so this wait's own success/timeout can be told apart from a
// stale firing left armed after an HA-reconnect recovery (f_hareconn out4).
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', '207dee7e272ef8ca');
msg.rr_wgen = g;
msg.rr_office_t0 = Date.now();   // office done? short-job check
return msg;

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
flow.set('rr_pending', '');
// Rachel's office (segment 9) runs as its own job after the 11-room sweep
// (2026-11-05: in one 12-segment call the robot started there, hit
// nogo_zone_detected and the whole sweep died). Back at the dock = done:
// stamp the office (out0 -> settle final + evt officedone). Home in under
// 2 min = it never really cleaned: no stamp, tell the owner, run moves on.
// No t0 (HA-reconnect recovery msg) = treated as done.
// out0 -> [d_55, evt: officedone], out1 -> [d_55], out2 -> notify
const t0 = msg.rr_office_t0;
const mins = t0 ? (Date.now() - t0) / 60000 : NaN;
if (!isNaN(mins) && mins < 2) {
    node.status({fill:'yellow', text:'office ended early: ' + mins.toFixed(1) + ' min'});
    return [null, msg, {notify: {title: "Vacuum: Rachel's office ended early",
        message: "Rachel's office was back at the dock after " + mins.toFixed(1) +
                 ' min. The run continues; the office is not marked cleaned.',
        tag: 'rr_short_zone', urgent: false}}];
}
node.status({fill:'green', text: isNaN(mins) ? 'office done (recovered)' : 'office done: ' + mins.toFixed(1) + ' min'});
return [msg, null, null];

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
// Heading home or idle beside the dock after a return: the stage dock watcher
// (f_dw, group 9) takes the stage over (one re-dock, alert, 30-min hold).
const _dw = flow.get('rr_dw');
if (_dw && _dw.state === 'watch' && _dw.wid === flow.get('rr_pending') && _dw.gen === msg.rr_wgen && _dw.retAt) {
    _dw.force = true; flow.set('rr_dw', _dw);
    node.status({fill:'yellow', text:'near the dock: dock watcher takes over'});
    return null;
}
flow.set('rr_pending', '');
msg.rr_stage = "Rachel's office (last)"; msg.rr_mins = 40; return msg;

// Arm 'wait battery ≥30% (office)': bump the wait generation + mark it pending,
// so the wait's own success/timeout can be told apart from a stale firing.
const g = (flow.get('rr_waitgen') || 0) + 1;
flow.set('rr_waitgen', g);
flow.set('rr_pending', '48ec4456670321ea');
msg.rr_wgen = g;
return msg;

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
flow.set('rr_pending', '');
return msg;

if (msg.rr_wgen !== flow.get('rr_waitgen')) { node.status({fill:'grey',shape:'ring',text:'stale wait ignored'}); return null; }
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return null; }
flow.set('rr_pending', '');
// The sweep can dock near 14%; app_segment_clean is refused on a flat battery
// and cat_mid would cancel the run. Not reaching 30% in 90 min skips the office
// only: no stamp, a notice, phase text, and on to d_55 so the mop gate still runs.
// out0 -> d_55, out1 -> tracker (officeskip), out2 -> notify
node.status({fill:'yellow', text:'office skipped: battery'});
return [msg, {rr_evt: 'officeskip'}, {notify: {title: "Vacuum: Rachel's office skipped",
    message: "The battery did not reach 30% within 90 min after the sweep, so Rachel's office was skipped. " +
             'The run continues; the office is not marked cleaned.',
    tag: 'rr_office_skipped', urgent: false}}];

if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return [null, null]; }
const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);

flow.set('rr_zone_t', Date.now());
const m = st('select.mr_slave_cleaning_mode');
if (m === 'vacuum' || m === undefined) { node.status({fill:'green',text:String(m)}); return [msg, null]; }
node.warn('cleaning mode is ' + m + ' after set; retrying once (O)');
node.status({fill:'yellow',text:'retry: was ' + m});
return [null, msg];

// Next mop step (owner, 2026-11-18): Node-RED owns the mop pass, one robot job
// per step, hard floors only, LVP first, then tile. Each step: cancel guard ->
// set_custom_mode [102] (s_mc1), set_water_box_custom_mode [201] (s_mc2),
// set_mop_mode [300] (s_mc3): vacuum and mop together in one pass -> then
// app_segment_clean with the step's segments (s_mseg) -> f_mstepchk polls
// every 30 s until the step's job has really finished. (set_mop_template_id
// is not supported by this robot, so it is not sent.)
// msg.rr_mop_idx = steps done so far. out0 -> s_mc1 (send the step),
// out1 -> tracker (phase "Mop pass 3/7 — Living room"), out2 -> f_64 (all 7
// finished: the only path that stamps rr_last_mop_run).
const STEPS = [
    {name: 'Front door entry', segments: [11]},
    {name: 'Hallway', segments: [10]},
    {name: 'Living room', segments: [12]},
    {name: 'Kitchen', segments: [13]},
    {name: 'Bathroom 1', segments: [5]},
    {name: 'Master bathroom', segments: [4]},
    {name: 'Half bath + Garage entrance + Laundry', segments: [7, 6, 8]},
];
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return [null, null, null]; }
if (msg.rr_mopgen !== flow.get('rr_mopgen')) { node.status({fill:'grey',shape:'ring',text:'stale mop pass ignored'}); return [null, null, null]; }
if (flow.get('rr_mop_water')) { node.status({fill:'red',text:'stopped: clean water ran out'}); return [null, null, null]; }
const i = msg.rr_mop_idx || 0;
if (i >= STEPS.length) {
    node.status({fill:'green', text:'all ' + STEPS.length + ' mop steps finished'});
    return [null, null, msg];
}
const s = STEPS[i];
msg.rr_step = {n: i + 1, of: STEPS.length, name: s.name, segments: s.segments.slice()};
msg.rr_step_t0 = Date.now();
msg.rr_step_started = 0;
msg.rr_step_home = 0;
const phase = 'Mop pass ' + (i + 1) + '/' + STEPS.length + ' — ' + s.name;
node.status({fill:'blue', text: phase + (msg.rr_step_retry ? ' (retry ' + msg.rr_step_retry + ')' : '')});
return [msg, {rr_evt: 'mopstep', rr_phase: phase}, null];

// Mop step finished? Polled every 30 s (d_mstep) after the step's
// app_segment_clean. One step = one robot job (2026-11-18 history):
//   started  : cleaning_2 on, vacuum cleaning or a *_cleaning status, or
//              cleaning_2 changed since the step was sent
//   finished : started, cleaning_2 off (the job closed; progress resets to 0)
//              and the robot home and settled for 90 s: status charging /
//              charging_complete (or vacuum docked), not washing_the_mop /
//              emptying_the_bin.
// None of these is "finished", and none is a failure: a mid-job mop wash
// (going_to_wash / washing, cleaning_2 stays on), a recharge pause (charging
// with cleaning_2 on; the robot resumes at 80 %), the bin empty and mop wash
// after the job, idle beside the dock after a failed dock (group 8 retries).
// Clean tank ran dry -> failed (never finished). 240 min per step -> failed.
// out0 -> f_mstep (next step), out1 -> d_mstep (poll again),
// out2 -> f_mopfail, out3 -> f_mretry (the job never started: send it again)
const C = { SETTLE_S: 90, START_MIN: 5, STEP_MAX_MIN: 240 };
const NONE = [null, null, null, null];
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return NONE; }
if (msg.rr_mopgen !== flow.get('rr_mopgen')) { node.status({fill:'grey',shape:'ring',text:'stale mop pass ignored'}); return NONE; }
if (flow.get('rr_mop_water')) { node.status({fill:'red',text:'stopped: clean water ran out'}); return NONE; }
const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);
const now = Date.now();
const step = msg.rr_step || {n: (msg.rr_mop_idx || 0) + 1, of: 7, name: '?'};
const label = 'mop step ' + step.n + '/' + step.of + ' (' + step.name + ')';
const t0 = msg.rr_step_t0 || now;
const c = _st['binary_sensor.mr_slave_cleaning_2'] || {};
const status = String(st('sensor.mr_slave_status_2') || '');
const vac = String(st('vacuum.mr_slave_2') || '');
if (st('binary_sensor.mr_slave_water_shortage_2') === 'on') {
    flow.set('rr_mop_water', true);
    flow.set('rr_mop_inpass', 0);
    msg.rr_mop_water = true;
    msg.rr_mop_reason = 'the clean-water tank ran out during ' + label + ', so the pass is marked incomplete. Refill the tank';
    node.status({fill:'red', text:'clean water ran out: ' + label});
    return [null, null, msg, null];
}
const changed = !!c.last_changed && Date.parse(c.last_changed) > t0;
if (!msg.rr_step_started && (c.state === 'on' || vac === 'cleaning' || /_cleaning$/.test(status) || changed)) msg.rr_step_started = now;
if (!msg.rr_step_started) {
    if ((now - t0) / 60000 >= C.START_MIN) {
        msg.rr_mop_reason = label + ' did not start within ' + C.START_MIN + ' min';
        node.status({fill:'yellow', text: label + ': not started, retrying'});
        return [null, null, null, msg];
    }
    node.status({fill:'blue', text: label + ': waiting for the job to start'});
    return [null, msg, null, null];
}
const settled = c.state === 'off' && !/wash|empty/.test(status)
    && (['charging', 'charging_complete'].includes(status) || vac === 'docked');
if (settled) {
    msg.rr_step_home = msg.rr_step_home || now;
    if ((now - msg.rr_step_home) / 1000 >= C.SETTLE_S) {
        node.status({fill:'green', text: label + ' finished after ' + Math.round((now - t0) / 60000) + ' min'});
        msg.rr_mop_idx = (msg.rr_mop_idx || 0) + 1;
        msg.rr_step_retry = 0;
        return [msg, null, null, null];
    }
} else {
    msg.rr_step_home = 0;
}
if ((now - t0) / 60000 >= C.STEP_MAX_MIN) {
    msg.rr_mop_reason = label + ' did not finish within ' + C.STEP_MAX_MIN + ' min';
    node.status({fill:'red', text: label + ': gave up after ' + C.STEP_MAX_MIN + ' min'});
    return [null, null, msg, null];
}
node.status({fill:'blue', text: label + ': ' + (status || vac || '?').replace(/_/g, ' ') + ', cleaning ' + (c.state || '?')});
return [null, msg, null, null];

// A mop step's commands failed (catch cat_mstep, e.g. a transient
// "Connection lost" from the robot) or its job never started (f_mstepchk out3).
// Like the daily start (cat_38 -> f_39): wait 60 s (d_mretry) and send the
// whole step again (modes + app_segment_clean). After 4 retries of the same
// step the pass fails (f_mopfail, rr_mop_failed).
// out0 -> d_mretry -> f_mstep (same step), out1 -> f_mopfail
const MAX = 4;
if (flow.get('rr_cancel')) { node.status({fill:'red',text:'cancelled'}); return [null, null]; }
if (msg.rr_mopgen !== flow.get('rr_mopgen') || flow.get('rr_mop_water')) { node.status({fill:'grey',shape:'ring',text:'stale mop pass ignored'}); return [null, null]; }
const step = msg.rr_step || {n: (msg.rr_mop_idx || 0) + 1, of: 7, name: '?'};
const what = (msg.error && msg.error.message) || msg.rr_mop_reason || 'command failed';
const n = (msg.rr_step_retry || 0) + 1;
msg.rr_step_retry = n;
delete msg.error;
if (n > MAX) {
    msg.rr_mop_reason = 'mop step ' + step.n + '/' + step.of + ' (' + step.name + ') could not be started after ' + MAX + ' retries (' + what + ')';
    node.status({fill:'red', text:'step ' + step.n + ': gave up after ' + MAX + ' retries'});
    return [null, msg];
}
delete msg.rr_mop_reason;
node.warn('mop step ' + step.n + '/' + step.of + ': ' + what + '; retry ' + n + '/' + MAX + ' in 60 s');
node.status({fill:'yellow', text:'step ' + step.n + ': retry ' + n + '/' + MAX + ' (' + what + ')'});
return [msg, null];

// "Mop all floors" (input_button.rr_mop_all_floors), 2026-11-18: the same 7
// Node-RED mop steps as the Wednesday pass, any day, with the same cancel and
// hand-stop handling. No battery wait (the robot recharges mid-step and resumes
// by itself). Stamps no room; rr_last_mop_run is stamped after 7/7 (f_64) like
// the weekly pass. Ignored while a daily run or another mop pass is live.
// out0 -> lo_mop_man -> f_59 (start mop pass), out1 -> tracker (start, manual)
const run = flow.get('rr_run', 'file') || {};
if (run.active && !run.cancelled && !flow.get('rr_cancel')) {
    node.warn('Mop all floors ignored: a run is in progress (' + (run.phase || '?') + ')');
    node.status({fill:'yellow', text:'ignored: a run is in progress'});
    return [null, null];
}
flow.set('rr_cancel', false);
flow.set('rr_pending', '');
flow.set('rr_mop_manual', true);
flow.set('rr_mop_pending', false);   // stall/stop alerts: no "today's mop will not run" line
flow.set('rr_mop_skip', false);
msg.rr_mop_manual = true;
node.status({fill:'blue', text:'manual mop started'});
return [msg, {rr_evt: 'start', rr_mop_manual: true}];

// Hand stop / dashboard cancel (owner, 2026-11-18), from f_ev_idle (rr_src
// 'hand') or the dashboard cancel button f_28 (rr_src 'button'):
//   - cancel the rest of the run: rr_cancel, bump rr_waitgen (drops every armed
//     stage / battery wait) and rr_mopgen (drops the mop-step poll), clear
//     rr_pending (so group 8 can retry the dock again)
//   - end the robot's job so it cannot resume on its own after recharging
//     (11-14 15:43, 11-16 16:23): vacuum.stop while a job is open or the robot
//     is moving (out0), then 30 s later f_hs_home sends it home unless it is
//     already home or heading home with the job ended (no stop needed: out1)
//   - one quiet note (urgent false) to both phones, only if a run was live
//   - restore the default vacuum mode once home (w_restore)
// out0 -> s_hs_stop -> d_hs, out1 -> d_hs, out2 -> notify, out3 -> w_restore, out4 -> tracker
const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);
const run = flow.get('rr_run', 'file') || {};
const live = !!run.active && !run.cancelled && !flow.get('rr_cancel');
const manual = !!flow.get('rr_mop_manual');
const button = msg.rr_src === 'button';
flow.set('rr_cancel', true);
flow.set('rr_waitgen', (flow.get('rr_waitgen') || 0) + 1);
flow.set('rr_pending', '');
flow.set('rr_mopgen', (flow.get('rr_mopgen') || 0) + 1);
flow.set('rr_mop_inpass', 0);
flow.set('rr_own_cmd_at', Date.now());
const status = String(st('sensor.mr_slave_status_2') || '');
const vac = String(st('vacuum.mr_slave_2') || '');
const jobOpen = st('binary_sensor.mr_slave_cleaning_2') === 'on'
    || ['cleaning', 'paused', 'returning'].includes(vac)
    || /_cleaning$|paused|returning|going_to_wash/.test(status);
const o = [null, null, null, {payload: 'restore'}, {rr_evt: button ? 'cancel' : 'idle'}];
const go = {payload: 'home', rr_hs_try: 0};
if (jobOpen) o[0] = go; else o[1] = go;
if (live) {
    o[2] = {notify: {title: 'Vacuum: stopped by hand',
        message: manual
            ? 'Stopped by hand — the rest of the mop is cancelled. Tap Mop all floors to restart.'
            : 'Stopped by hand — the rest of today\'s run is cancelled. Tap Daily clean to restart.',
        tag: 'rr_hand_stop', urgent: false}};
}
node.status({fill: live ? 'red' : 'grey', text: (button ? 'cancel button' : (msg.rr_hand || 'hand stop')) +
    (live ? ' — run cancelled' : ' — no run') + (jobOpen ? ', stopping job' : '')});
return o;

// 30 s after a hand stop (or the cancel button): get the robot home.
//   job still open (cleaning_2 on and vacuum cleaning / paused): stop again (out0)
//   home (docked / charging / washing / emptying): nothing to do
//   returning with the job ended: already heading home, nothing to do
//   anything else (idle on the floor after the stop): return_to_base (out1)
// Loops via d_hs (cat_hs catches a failed stop / return) at most 4 times.
// A new run (rr_cancel false again) stops the loop.
if (!flow.get('rr_cancel')) { node.status({fill:'grey',shape:'ring',text:'new run started'}); return [null, null]; }
const n = (msg.rr_hs_try || 0) + 1;
msg.rr_hs_try = n;
delete msg.error;
if (n > 4) { node.warn('hand stop: robot still not home after 4 tries'); node.status({fill:'red',text:'gave up after 4 tries'}); return [null, null]; }
const _ha = global.get('homeassistant') || {};
const _st = (Object.values(_ha).find(v => v && v.states) || {}).states || {};
const st = id => (_st[id] && _st[id].state);
const status = String(st('sensor.mr_slave_status_2') || '');
const vac = String(st('vacuum.mr_slave_2') || '');
const cleaningOn = st('binary_sensor.mr_slave_cleaning_2') === 'on';
const home = vac === 'docked' || ['charging', 'charging_complete', 'washing_the_mop', 'emptying_the_bin'].includes(status);
flow.set('rr_own_cmd_at', Date.now());
if (cleaningOn && ['cleaning', 'paused'].includes(vac)) { node.status({fill:'yellow',text:'job still open: stop again'}); return [msg, null]; }
if (home) { node.status({fill:'green',text:'home (' + (status || vac) + ')'}); return [null, null]; }
if (vac === 'returning' && !cleaningOn) { node.status({fill:'green',text:'heading home'}); return [null, null]; }
node.status({fill:'yellow',text:'return_to_base (' + (status || vac || '?') + ')'});
return [null, msg];

// Node-RED's own HA user (the token's user). f_ev_idle tells Node-RED's own
// vacuum commands from a person's by context.user_id; learning the id here
// avoids hard-coding it. Until it is known f_ev_idle falls back to the
// own-command window.
const id = msg.payload && msg.payload.id;
if (!id) { node.status({fill:'yellow',text:'no user id in reply'}); return null; }
flow.set('rr_nr_uid', String(id));
node.status({fill:'green', text:'own user ' + String(id).slice(0, 8) + '…'});
return null;

// Hand stop from a service call (review fix, 2026-11-18). f_ev_idle needs a
// user id on the state change (rule i) or a paused step (rule ii). A dock or
// stop call that carries no user goes cleaning -> returning with no user, the
// same as a natural job end, so the stage wait saw "charging" and the next
// stage started. The HA HomeKit bridge calls services with Context() and no
// user id (homekit/accessories.py async_call_service_and_wait); HomeKit "off"
// on a vacuum = vacuum.return_to_base (type_switches.py Vacuum).
// So: a call_service event (ev_vaccall, domain vacuum) for stop / pause /
// return_to_base / turn_off, or send_command app_stop / app_pause / app_charge,
// targeting vacuum.mr_slave_2 (entity_id string or list, in service_data or
// target, or "all"), whose context user is NOT Node-RED's own (rr_nr_uid; no
// user id = not own), while a run or mop pass is live -> f_hstop.
// rr_nr_uid not known yet -> a call counts as Node-RED's own only inside the
// own-command signals (rr_own_cmd_at, stamped before every Node-RED stop /
// return: f_hstop, f_hs_home, f_own_dock (group 8), f_dw (group 9); or
// rr_dock.busy / rr_dw.state 'retry').
// The robot's physical button never makes a call_service event: f_ev_idle rule (ii).
const OWN_MS = 2 * 60 * 1000;
const ENT = 'vacuum.mr_slave_2';
const SERVICES = ['stop', 'pause', 'return_to_base', 'turn_off'];
const COMMANDS = ['app_stop', 'app_pause', 'app_charge'];
const e = msg.payload || {};
const d = e.event || {};
if (d.domain !== 'vacuum') return null;
const sd = d.service_data || {};
const hit = SERVICES.includes(d.service)
    || (d.service === 'send_command' && COMMANDS.includes(String(sd.command || '')));
if (!hit) return null;
const ids = [].concat(sd.entity_id || [], (d.target && d.target.entity_id) || [])
    .reduce((a, x) => a.concat(Array.isArray(x) ? x : String(x).split(',')), [])
    .map(x => String(x).trim());
if (!ids.includes(ENT) && !ids.includes('all')) return null;
const run = flow.get('rr_run', 'file') || {};
if (!run.active || run.cancelled || flow.get('rr_cancel')) return null;
const uid = (e.context && e.context.user_id) || '';
const ownUid = flow.get('rr_nr_uid') || '';
const dk = flow.get('rr_dock') || {};
const dw = flow.get('rr_dw') || {};
const ownCmd = (Date.now() - (flow.get('rr_own_cmd_at') || 0)) < OWN_MS || !!dk.busy || dw.state === 'retry';
const own = ownUid ? uid === ownUid : ownCmd;
if (own) { node.status({fill:'grey', shape:'ring', text:'own call ' + d.service}); return null; }
const what = d.service === 'send_command' ? 'send_command ' + sd.command : d.service;
msg.rr_src = 'hand';
msg.rr_hand = 'service call ' + what + (uid ? ' by a person' : ' with no user (HomeKit?)');
node.status({fill:'red', text:'hand stop: ' + msg.rr_hand});
return msg;

// Group 8's return_to_base is Node-RED's own: stamp rr_own_cmd_at first, so the
// hand-stop classifiers (f_ev_idle, f_hcall) never take it for a person.
flow.set('rr_own_cmd_at', Date.now());
return msg;
